/* Explicit preparation only: opening this screen never downloads weights. */
const ModelManager=(()=>{
 const E=id=>document.getElementById(id);let busy=false,cancel=null,epoch=0,needed='',requestedPair=null,refreshEpoch=0;
 const currentPair=()=>StudyLanguages.pair(RecognitionSettings.read().writing,E('betaTarget').value);
 const pair=()=>requestedPair||currentPair();
 const ocrId=()=>{const s=RecognitionSettings.read();return s.ocr==='paddle'?'paddle':s.writing==='auto'?`ocr:${s.ocr}:auto`:`ocr:${s.ocr}:${StudyLanguages.sources[s.writing].ocr}`};
 function status(t){E('modelStatus').textContent=t}
 async function nativeState(p=pair()){try{return 'Translator'in self?await Translator.availability({sourceLanguage:p.source,targetLanguage:p.target}):'unavailable'}catch{return 'unavailable'}}
 async function open(id='',reason='',p=null){needed=id;requestedPair=p;SettingsUI.open('models');status(reason||'다운로드 버튼을 눌러 모델을 준비하세요. 준비 후 원래 기능을 다시 실행하세요.');await refresh()}
 async function ensure(id,p){if(id==='ocr:auto'||/^ocr:(best|fast):auto$/.test(id)){const preset=id==='ocr:auto'?RecognitionSettings.read().ocr:id.split(':')[1];for(const lang of ['eng','kor','jpn','jpn_vert'])if(!await ensure('ocr:'+preset+':'+lang))return false;return true}if(busy){await open(id,'모델 준비가 진행 중입니다. 완료 후 다시 실행하세요.',p);return false}const ready=id==='browser'?await nativeState(p)==='available':id&&await ModelStorage.status(id).then(r=>r.ready);if(!ready){await open(id,'필요한 모델이 없습니다. 다운로드하거나 준비된 다른 엔진을 선택한 뒤 다시 실행하세요.',p);return false}return true}
 async function refresh(){const token=epoch,refreshToken=++refreshEpoch;try{const rows=await ModelStorage.list();if(token!==epoch)return;const n=await nativeState();if(token!==epoch||refreshToken!==refreshEpoch)return;const host=E('modelRows');host.replaceChildren();const native={id:'browser',kind:'translation',label:'브라우저 내장 · 현재 인식/도착 언어',state:({available:'사용 가능',downloadable:'다운로드 필요',downloading:'준비 중',unavailable:'지원하지 않음'})[n]||n,ready:n==='available',size:'브라우저 관리 · 앱에서 삭제할 수 없습니다.'};
 for(const [title,items] of [['OCR 모델',rows.filter(r=>r.kind==='ocr'||r.kind==='ocr-paddle')],['번역 모델',[native,...rows.filter(r=>r.kind==='translation')]]]){const group=document.createElement('section');group.className='model-group';group.setAttribute('aria-label',title);const heading=document.createElement('h4');heading.textContent=title;group.append(heading);
 for(const r of items){const row=document.createElement('div');row.dataset.modelId=r.id;row.className='storage-row'+((r.id===needed||r.parts?.includes(needed)||needed===`ocr:${r.preset}:auto`)?' model-needed':'');const label=document.createElement('b');label.textContent=r.label;const info=document.createElement('p');info.textContent=r.state+' · '+r.size;const actions=document.createElement('div');actions.className='beta-actions';const download=document.createElement('button');download.textContent=r.ready?'준비 완료':'다운로드';download.disabled=busy||r.ready||(r.id==='browser'&&n==='unavailable');download.onclick=()=>downloadModel(r.id);const remove=document.createElement('button');remove.textContent='삭제';remove.disabled=busy||r.id==='browser'||!r.count;remove.onclick=()=>removeModel(r.id);actions.append(download,remove);if(r.ready){const use=document.createElement('button');use.textContent='이 엔진 사용';use.disabled=busy;use.onclick=()=>{if(r.id==='paddle')RecognitionSettings.set({ocr:'paddle'});else if(r.kind==='ocr')RecognitionSettings.set({ocr:r.preset});else BetaTranslation.selectEngine(r.id);status(r.label+'을 선택했습니다. 닫은 뒤 원래 기능을 다시 실행하세요.')};actions.append(use)}row.append(label,info,actions);group.append(row)}host.append(group)}E('modelCancel').hidden=!busy;E('modelRefresh').disabled=busy;}catch(e){status('모델 상태 확인 실패: '+e.message)}}

 async function downloadModel(id){if(busy)return;busy=true;const token=++epoch;let worker,native,task,controller;status('모델 다운로드 준비 중…');E('modelCancel').hidden=false;cancel=()=>{epoch++;controller?.abort();task?.cancel();worker?.terminate();native?.destroy();busy=false;cancel=null;status(id==='browser'?'준비를 취소했습니다. 브라우저 자체 다운로드는 계속될 수 있습니다.':'다운로드를 취소했습니다. 일부 번역 파일은 남을 수 있으며 삭제할 수 있습니다.');refresh()};try{
 // Native create must start directly from this button's user activation.
 let nativePromise;if(id==='browser'){const p=pair();nativePromise=Translator.create({sourceLanguage:p.source,targetLanguage:p.target,monitor(m){m.addEventListener('downloadprogress',e=>{if(token===epoch)status('브라우저 언어 팩 준비 · '+Math.round(e.loaded*100)+'%')})}});nativePromise.catch(()=>{})}
 await BetaTranslation.unload(!!bootstrap);refresh();
 if(id==='browser'){native=await nativePromise;if(token!==epoch){native.destroy();return}native.destroy();native=null;if(await nativeState()!=='available')throw Error('브라우저 언어 팩이 준비되지 않았습니다.');}
 else if(id==='paddle'){controller=new AbortController();await PaddleModels.prepare(controller.signal,t=>{if(token===epoch){status(t);if(bootstrap)globalThis.StartupUI?.ocr(t)}});}
 else if(id.startsWith('ocr:')){controller=new AbortController();const ids=ModelStorage.catalog.find(r=>r.id===id)?.parts||[id];for(const member of ids){if((await ModelStorage.status(member)).ready)continue;const {preset,lang}=ModelStorage.parseOCR(member),response=await fetch(`models/ocr/${preset}/${lang}.traineddata.gz`,{signal:controller.signal});if(!response.ok)throw Error('OCR 모델 파일을 받지 못했습니다.');const reader=response.body.getReader(),chunks=[];let total=0;while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);total+=value.length;if(token!==epoch)return;status('Tesseract '+(preset==='fast'?'경량':'정밀')+' · '+(ids.indexOf(member)+1)+'/'+ids.length+' · '+(total/1048576).toFixed(1)+'MB')}const data=new Uint8Array(total);let offset=0;for(const part of chunks){data.set(part,offset);offset+=part.length}if(token!==epoch)return;await ModelStorage.writeOCR(preset,lang,data)}}

 else{worker=new Worker('./translation-worker.js?v=0.33.0-beta.1',{type:'module'});task=createTranslationTask(worker,{id:token,engine:id,operation:'prepare',download:true},t=>{if(token===epoch){status(t);if(bootstrap)globalThis.StartupUI?.ocr(t)}});await task.promise;if(token!==epoch)return;if(!(await ModelStorage.status(id)).ready)throw Error('파일이 모두 저장되지 않았습니다. 저장 공간을 확인하고 다시 다운로드하세요.');}
 if(token===epoch)status('모델 준비 완료. 닫은 뒤 텍스트 선택 또는 번역을 다시 실행하세요.');
 }catch(e){if(token===epoch)status('모델 준비 실패: '+e.message)}finally{worker?.terminate();if(token===epoch){busy=false;cancel=null;await refresh()}}}
 async function removeModel(id){if(busy)return;E('cacheConfirmTitle').textContent='모델 캐시 삭제';const item=ModelStorage.catalog.find(r=>r.id===id);E('cacheConfirmText').textContent=(item?.label||id)+' 모델을 삭제할까요? 책과 설정은 유지하며 다시 사용하려면 다운로드해야 합니다.';E('cacheConfirm').showModal();E('cacheDeleteYes').onclick=async()=>{E('cacheConfirm').close();if(busy)return;busy=true;try{await BetaTranslation.unload();await ModelStorage.remove(id);status('모델을 삭제했습니다.')}catch(e){status('삭제 실패: '+e.message)}finally{busy=false;await refresh()}}}
 let bootstrap=null;async function prepareDefaultOcr(){if(bootstrap)return bootstrap;bootstrap=(async()=>{const ids=['paddle'];globalThis.StartupUI?.ocr('저장된 OCR 모델 확인 중…');E('ocrRetry').hidden=true;try{if(busy)throw Error('다른 모델 준비가 진행 중입니다. 잠시 뒤 다시 시도하세요.');for(const id of ids){if((await ModelStorage.status(id)).ready)continue;E('ocrStartupStatus').textContent=id==='paddle'?'PaddleOCR 준비 중 · 약 60.8MB':'Tesseract 정밀 준비 중 · 약 50.3MB · '+id.split(':').at(-1);E('ocrBootNotice').hidden=false;E('ocrBootNotice').textContent=E('ocrStartupStatus').textContent;await downloadModel(id);if(!(await ModelStorage.status(id)).ready)throw Error('인터넷 연결 또는 저장 공간을 확인하고 다시 시도하세요.')}E('ocrStartupStatus').textContent='기본 OCR 준비 완료 · PaddleOCR';E('ocrBootNotice').hidden=true;}catch(e){E('ocrStartupStatus').textContent='기본 OCR 준비 미완료 · '+e.message;E('ocrRetry').hidden=false;E('ocrBootNotice').hidden=false;E('ocrBootNotice').textContent='OCR 준비 미완료 · 설정 → OCR 설정에서 다시 시도하세요.';}finally{bootstrap=null}})();return bootstrap}
 function init(){E('modelRefresh').onclick=refresh;E('modelCancel').onclick=()=>cancel?.();E('cacheDeleteNo').onclick=()=>E('cacheConfirm').close();E('ocrModels').onclick=()=>open(ocrId());E('ocrRetry').onclick=prepareDefaultOcr;}
 return {init,open,ensure,ocrId,prepareDefaultOcr,isBusy:()=>busy,refresh};
})();
globalThis.ModelManager=ModelManager;
ModelManager.init();
